'use strict';
// A deliberately controlled structural case, not measured game damage.
module.exports=function(c){const m=c.PlannerData.real,p=c.PlannerData.profile(m),jobs=['job-1','job-5','job-0','job-2'],weapons=['paradox-staff','gun','moon','dharma-staff'];p.characters.forEach((ch,i)=>ch.levels={[jobs[i]]:80});p.inventory.forEach(row=>row.count=4);const base=m.jobs.find(j=>j.id==='job-1').levels[80];p.baseOverrides={'0:job-1':{level:80,cost:base.cost,stats:{...base.stats,magic:2000,mp:1500}}};const actors=weapons.map((weapon,member)=>({member,weapon,job:jobs[member],limitBreak:0,initial:true,armors:[],hearts:member===1?['phantom-dragon-awakened','donburi-king']:[],inherit:member===2?'keki':'',inheritLevel:member===2?1:0,inheritLimitBreak:0,pathUnlocked:true,encoreUnlocked:member===3})),enemy={name:'補完する補助の構造検証',race:'その他',defense:1000,count:1,typeResistance:0,enemyTension:0,elements:Object.fromEntries(c.AutoDamage.elements.map(e=>[e,0]))},settings={objective:'damage',turns:2,hp:1e8,allowAI:true,newWorldGoal:'白'},config={actors,enemy,domain:'auto',aiPolicy:'assume-selected',strictDurations:true,actions:[1,2].flatMap(turn=>[0,1,2,3].map(actor=>({actor,turn,skill:actor===0?'forbidden-burst':'wait',target:actor})))};const reference={...config,actions:[{actor:1,turn:1,skill:'tokumori',target:0},{actor:3,turn:1,skill:'dharma-prayer',target:0},{actor:2,turn:1,skill:'rondo'},{actor:0,turn:1,skill:'true-magic-release',aiSkill:'forbidden-burst'},{actor:1,turn:2,skill:'wait'},{actor:2,turn:2,skill:'rondo'},{actor:0,turn:2,skill:'forbidden-burst'},{actor:3,turn:2,skill:'encore',target:0},{actor:0,turn:2,skill:'forbidden-burst'}]};return {master:m,profile:p,settings,config,reference};};
